import type { Metadata } from "next"

import { RenewalScreen } from "./renewal-screen"

export const metadata: Metadata = {
  title: "更新のお手続き | 定期保険",
  description:
    "満期が近い定期保険について、いまの契約と更新後の条件をくらべて、更新するかどうかを決める画面。",
}

export default function PolicyRenewalPage() {
  return <RenewalScreen />
}

"use client"

/**
 * 「いまの契約」と「更新後」を項目ごとに並べる表。
 *
 * @gunjo/ui に前後比較（before / after）用のコンポーネントが無かったので、
 * Table + Delta + Badge を組み合わせて自前で組んだ部分。
 *
 * アクセシビリティの方針:
 *  - 本物の <table>。列見出しは th[scope="col"]、項目名は th[scope="row"]。
 *    スクリーンリーダーの表モードで「毎月の保険料 / 更新後 / 19,480円」と読める。
 *  - 表モードを使わずに上から順に読む人のために、表の前に
 *    「どこが変わるか」を1文で置く（sr-only ではなく全員に見せる）。
 *  - 変更ありは色だけで示さず、Badge のテキストと Delta のラベルで示す。
 */

import { Badge, Delta, Table, TableBody, TableCaption, TableCell, TableHead, TableHeader, TableRow, type DeltaProps } from "@gunjo/ui"
import { IconArrowBarToUp, IconEqual } from "@tabler/icons-react"

export type ComparisonRow = {
  key: string
  /** 項目名（行見出し） */
  label: string
  /** 項目名の補足。専門語をそのまま出さないための言い換え */
  labelNote?: string
  current: string
  next: string
  /** 更新で変わる項目か */
  changed: boolean
  /** 変化量。数値で言える項目だけ渡す */
  delta?: DeltaProps
}

export function ComparisonTable({
  rows,
  currentHeading,
  nextHeading,
  caption,
}: {
  rows: ComparisonRow[]
  currentHeading: string
  nextHeading: string
  caption: string
}) {
  const changed = rows.filter((r) => r.changed)
  const same = rows.filter((r) => !r.changed)

  return (
    <div className="flex flex-col gap-3">
      <p className="text-sm leading-6 text-foreground">
        変わるのは{" "}
        <span className="font-semibold">
          {changed.map((r) => r.label).join(" と ")}
        </span>{" "}
        の{changed.length}つです。
        {same.length > 0 && `${same.map((r) => r.label).join("と")}は変わりません。`}
      </p>

      <Table className="caption-top text-xs">
        <TableCaption className="border-b border-t-0 text-xs">{caption}</TableCaption>
        <TableHeader>
          <TableRow>
            <TableHead scope="col" className="w-[26%] px-2">
              項目
            </TableHead>
            <TableHead scope="col" className="w-[30%] px-2">
              {currentHeading}
            </TableHead>
            <TableHead scope="col" className="px-2 text-foreground">
              {nextHeading}
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.key}>
              <TableHead
                scope="row"
                className="h-auto px-2 py-3 align-top font-medium text-foreground"
              >
                {row.label}
                {row.labelNote && (
                  <span className="mt-0.5 block text-[11px] font-normal leading-4 text-muted-foreground">
                    {row.labelNote}
                  </span>
                )}
              </TableHead>
              <TableCell className="px-2 py-3 align-top tabular-nums text-muted-foreground">
                {row.current}
              </TableCell>
              <TableCell className="px-2 py-3 align-top">
                <span className="block text-sm font-semibold tabular-nums text-foreground">
                  {row.next}
                </span>
                <span className="mt-1 flex flex-wrap items-center gap-1">
                  {row.changed ? (
                    <Badge variant="warning" size="sm" icon={<IconArrowBarToUp />}>
                      変わります
                    </Badge>
                  ) : (
                    <Badge variant="secondary" size="sm" icon={<IconEqual />}>
                      変わりません
                    </Badge>
                  )}
                  {row.delta && <Delta showLabel className="text-xs" {...row.delta} />}
                </span>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

/**
 * 定期保険 更新判断画面のダミーデータ。
 * 実在の保険会社名・商品名は使っていない。金額・年齢はすべて架空。
 */

/** SSR とクライアントで残日数がずれないよう、「今日」は固定値で持つ。 */
export const TODAY = "2026-08-08"

/** 満期日（この日までは今の保障が続く）。 */
export const MATURITY_DATE = "2026-11-30"
/** 手続きの締切（満期日の14日前）。 */
export const APPLY_DEADLINE = "2026-11-16"
export const DEADLINE_DAYS_BEFORE_MATURITY = 14
/** 別商品への切り替えだけ締切が早い（満期日の45日前）。 */
export const SWITCH_DEADLINE = "2026-10-16"
/** 更新後の条件が始まる日。 */
export const NEW_TERM_START = "2026-12-01"

export const policy = {
  holderName: "田中 陽子",
  policyNumber: "7213-448-902",
  productName: "定期保険（10年更新型）",
  /** 更新時点の年齢 */
  ageAtRenewal: 45,
  /** 契約したときの年齢 */
  ageAtStart: 35,
  current: {
    amountManYen: 3000,
    termYears: 10,
    monthlyPremium: 8240,
    endAge: 45,
    coverUntil: "2026年11月30日",
  },
  renewed: {
    amountManYen: 3000,
    termYears: 10,
    monthlyPremium: 19480,
    endAge: 55,
    coverUntil: "2036年11月30日",
  },
} as const

/** 更新後の保険料（45歳・10年）。保険金額100万円あたりの単価 + 基本料。 */
export function premiumFor(amountManYen: number): number {
  return Math.round(700 + amountManYen * 6.26)
}

export const AMOUNT_MIN = 500
export const AMOUNT_MAX = 3000
export const AMOUNT_STEP = 100

/** 更新期間（10年）の月数。 */
export const RENEWAL_MONTHS = policy.renewed.termYears * 12

/** 切り替え候補の別商品（保険料が上がらないタイプ）。 */
export const switchPlan = {
  name: "終身タイプ（保険料が変わらない保険）",
  amountManYen: 500,
  monthlyPremium: 12600,
  coverUntil: "一生涯",
}

export type PathId = "renew" | "reduce" | "switch" | "stop"

export function formatJpDate(iso: string): string {
  const [y, m, d] = iso.split("-").map(Number)
  const weekday = ["日", "月", "火", "水", "木", "金", "土"][
    new Date(Date.UTC(y, m - 1, d)).getUTCDay()
  ]
  return `${y}年${m}月${d}日（${weekday}）`
}

export function formatManYen(manYen: number): string {
  return manYen >= 10000
    ? `${(manYen / 10000).toLocaleString("ja-JP")}億円`
    : `${manYen.toLocaleString("ja-JP")}万円`
}

export function formatYen(yen: number): string {
  return `${yen.toLocaleString("ja-JP")}円`
}

"use client"

import * as React from "react"
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
  Alert,
  AlertDescription,
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
