  IconBuildingStore,
  IconCalendarEvent,
  IconCheck,
  IconCircleCheck,
  IconCoin,
  IconDeviceMobile,
  IconExchange,
  IconFileText,
  IconInfoCircle,
  IconMessageCircle,
  IconPhone,
  IconPlayerStop,
  IconRefresh,
} from "@tabler/icons-react"

import { ComparisonTable, type ComparisonRow } from "./comparison-table"
import {
  AMOUNT_MAX,
  AMOUNT_MIN,
  AMOUNT_STEP,
  APPLY_DEADLINE,
  DEADLINE_DAYS_BEFORE_MATURITY,
  MATURITY_DATE,
  NEW_TERM_START,
  RENEWAL_MONTHS,
  SWITCH_DEADLINE,
  TODAY,
  formatJpDate,
  formatManYen,
  formatYen,
  policy,
  premiumFor,
  switchPlan,
  type PathId,
} from "./data"

type ViewState = "ready" | "loading" | "empty" | "done"

const monthlyDiff = policy.renewed.monthlyPremium - policy.current.monthlyPremium
const totalDiff = monthlyDiff * RENEWAL_MONTHS

/* -------------------------------------------------------------------------- */
/* 比較表のデータ                                                              */
/* -------------------------------------------------------------------------- */

const comparisonRows: ComparisonRow[] = [
  {
    key: "amount",
    label: "保険金額",
    labelNote: "万一のときに受け取れるお金",
    current: formatManYen(policy.current.amountManYen),
    next: formatManYen(policy.renewed.amountManYen),
    changed: false,
  },
  {
    key: "premium",
    label: "毎月の保険料",
    labelNote: "毎月お支払いいただく金額",
    current: formatYen(policy.current.monthlyPremium),
    next: formatYen(policy.renewed.monthlyPremium),
    changed: true,
    delta: {
      value: monthlyDiff,
      format: (v) => formatYen(Math.abs(v)),
      labels: { positive: "増えます", negative: "減ります", zero: "変わりません" },
      tones: { positive: "warning", negative: "success", zero: "muted" },
    },
  },
  {
    key: "term",
    label: "保険期間",
    labelNote: "1回の契約が続く長さ",
    current: `${policy.current.termYears}年`,
    next: `${policy.renewed.termYears}年`,
    changed: false,
  },
  {
    key: "end-age",
    label: "満了年齢",
    labelNote: "保障が終わるときの年齢",
    current: `${policy.current.endAge}歳`,
    next: `${policy.renewed.endAge}歳`,
    changed: true,
    delta: {
      value: policy.renewed.endAge - policy.current.endAge,
      format: (v) => `${Math.abs(v)}歳分`,
      labels: { positive: "のびます", negative: "短くなります", zero: "変わりません" },
      tones: { positive: "info", negative: "warning", zero: "muted" },
    },
  },
  {
    key: "cover-until",
    label: "保障が続くのは",
    current: `${policy.current.coverUntil}まで`,
    next: `${policy.renewed.coverUntil}まで`,
    changed: true,
    delta: {
      value: policy.renewed.termYears,
      format: (v) => `${Math.abs(v)}年分`,
      labels: { positive: "のびます", negative: "短くなります", zero: "変わりません" },
      tones: { positive: "info", negative: "warning", zero: "muted" },
    },
  },
]

/* -------------------------------------------------------------------------- */
/* 選べる道                                                                    */
/* -------------------------------------------------------------------------- */

const PATH_LABEL: Record<PathId, string> = {
  renew: "そのまま更新する",
  reduce: "保険金額を下げて更新する",
  switch: "別の商品に切り替える",
  stop: "更新しない",
}

type RequiredDoc = { id: string; label: string; description?: string }

const REQUIRED_DOCS: Record<PathId, RequiredDoc[]> = {
  renew: [],
  reduce: [
    { id: "login", label: "マイページのログイン情報", description: "ご契約者ご本人であることの確認に使います" },
    { id: "id", label: "本人確認書類の撮影", description: "運転免許証・マイナンバーカードなど、いずれか1点" },
  ],
  switch: [
    { id: "id2", label: "本人確認書類", description: "運転免許証・マイナンバーカードなど、いずれか1点" },
    { id: "health", label: "健康状態のご申告書", description: "現在の通院・服薬・過去の入院についてお答えいただきます" },
    { id: "bank", label: "保険料をお支払いいただく口座の情報", description: "通帳またはキャッシュカード" },
    { id: "meet", label: "担当者との面談（オンライン可）", description: "内容のご説明のため、30分ほどお時間をいただきます" },
  ],
  stop: [
    { id: "login2", label: "マイページのログイン情報" },
    { id: "id3", label: "本人確認書類の撮影", description: "運転免許証・マイナンバーカードなど、いずれか1点" },
