}

const PROCEDURE_META: Record<PathId, { channel: string; online: boolean; deadline: string; note: string }> = {
  renew: {
    channel: "お手続きは要りません",
    online: true,
    deadline: `${formatJpDate(APPLY_DEADLINE)}まで（変更したくなった場合）`,
    note: "この画面で「更新を確定する」を押していただくと、確認の通知をお送りします。押さなくても内容は同じです。",
  },
  reduce: {
    channel: "オンラインだけで完了します",
    online: true,
    deadline: `${formatJpDate(APPLY_DEADLINE)}まで`,
    note: "書類の郵送は要りません。画面で保険金額を決めて、本人確認書類を撮影していただきます。",
  },
  switch: {
    channel: "書類のやり取りが必要です",
    online: false,
    deadline: `${formatJpDate(SWITCH_DEADLINE)}まで（他の道より1か月早い締切です）`,
    note: "新しい契約のお申し込みになるため、健康状態のご申告と、担当者からのご説明が必要です。",
  },
  stop: {
    channel: "オンラインだけで完了します",
    online: true,
    deadline: `${formatJpDate(APPLY_DEADLINE)}まで`,
    note: `お申し出のあとでも、${formatJpDate(MATURITY_DATE)}までは取り消せます。`,
  },
}

function timelineFor(pathId: PathId) {
  if (pathId === "stop") {
    return [
      { time: "すぐ", title: "受付が完了します", description: "この画面と、ご登録のメールに受付番号が出ます。", variant: "success" as const },
      { time: "3営業日以内", title: "内容の確認のご連絡", description: "行き違いがないか、当社から確認のお知らせをお送りします。" },
      { time: formatJpDate(MATURITY_DATE), title: "この日まで保障は続きます", description: "この日までに気が変わった場合は取り消せます。" },
      { time: formatJpDate(NEW_TERM_START), title: "保障が終わります", description: "この日以降の保険料の引き落としもありません。" },
    ]
  }
  if (pathId === "switch") {
    return [
      { time: "すぐ", title: "お申し込みの受付", description: "受付番号が出ます。まだ新しい契約は成立していません。", variant: "success" as const },
      { time: "1週間ほど", title: "健康状態の確認", description: "ご申告の内容を確認します。追加のご質問をすることがあります。" },
      { time: "2〜3週間ほど", title: "お引き受けの可否のご連絡", description: "お引き受けできる場合は、条件とあわせてお知らせします。" },
      { time: formatJpDate(NEW_TERM_START), title: "新しい保障が始まります", description: "いまの契約はこの日の前日で終わります。" },
    ]
  }
  return [
    { time: "すぐ", title: "受付が完了します", description: "この画面と、ご登録のメールに受付番号が出ます。", variant: "success" as const },
    { time: "3営業日以内", title: "内容の確認のご連絡", description: "登録された内容をお知らせします。訂正はこの間にできます。" },
    { time: formatJpDate(NEW_TERM_START), title: "新しい条件が始まります", description: "この日から保険料と保障の内容が切り替わります。" },
    { time: "12月中旬ごろ", title: "新しい保険証券のお届け", description: "書面またはマイページでご確認いただけます。" },
  ]
}

/* -------------------------------------------------------------------------- */
/* 画面                                                                        */
/* -------------------------------------------------------------------------- */

export function RenewalScreen() {
  const [view, setView] = React.useState<ViewState>("ready")
  const [pathId, setPathId] = React.useState<PathId | null>(null)
  const [amountManYen, setAmountManYen] = React.useState(1500)
  const [checkedDocs, setCheckedDocs] = React.useState<string[]>([])
  const [confirmOpen, setConfirmOpen] = React.useState(false)
  const [submitting, setSubmitting] = React.useState(false)
  const pathSectionRef = React.useRef<HTMLDivElement>(null)

  const reducedPremium = premiumFor(amountManYen)

  const chosenPremium =
    pathId === "renew" ? policy.renewed.monthlyPremium
      : pathId === "reduce" ? reducedPremium
        : pathId === "switch" ? switchPlan.monthlyPremium
          : pathId === "stop" ? 0
            : null

  function handleSubmit() {
    setSubmitting(true)
    window.setTimeout(() => {
      setSubmitting(false)
      setConfirmOpen(false)
      setView("done")
    }, 900)
  }

  return (
    <div className="mx-auto flex min-h-dvh w-full max-w-[430px] flex-col bg-background">
      <PageHeader
        title="更新のお手続き"
        subtitle={`${policy.productName}・証券番号 ${policy.policyNumber}`}
        onBack={() => undefined}
        actions={
          <Button variant="ghost" size="sm" aria-label="このページのヘルプ">
            <Icon icon={IconInfoCircle} size="sm" decorative />
          </Button>
        }
      />

      <DemoStateSwitch value={view} onChange={setView} />

      {view === "loading" && <LoadingView />}
      {view === "empty" && <EmptyView onReset={() => setView("ready")} />}
      {view === "done" && (
        <DoneView
          pathId={pathId ?? "renew"}
          premium={chosenPremium ?? policy.renewed.monthlyPremium}
          amountManYen={pathId === "reduce" ? amountManYen : policy.renewed.amountManYen}
          onBack={() => setView("ready")}
        />
      )}

      {view === "ready" && (
        <>
          <main className="flex flex-1 flex-col gap-5 px-4 pb-6 pt-4">
            <Stepper
              steps={[
                { label: "くらべる", state: "completed" },
                { label: "えらぶ", state: pathId ? "completed" : "current" },
                { label: "手続き", state: pathId ? "current" : "upcoming" },
              ]}
            />

            <DeadlineSection />
            <ComparisonSection />

            <div ref={pathSectionRef}>
              <PathSection
                pathId={pathId}
                onChange={(v) => {
                  setPathId(v)
                  setCheckedDocs([])
                }}
                amountManYen={amountManYen}
                onAmountChange={setAmountManYen}
                reducedPremium={reducedPremium}
                checkedDocs={checkedDocs}
                onToggleDoc={(id, checked) =>
                  setCheckedDocs((prev) => (checked ? [...prev, id] : prev.filter((x) => x !== id)))
                }
                onJumpToReduce={() => {
                  setPathId("reduce")
                  setCheckedDocs([])
                  pathSectionRef.current?.scrollIntoView({ behavior: "smooth", block: "start" })
                }}
              />
            </div>

            <HelpSection />

            <p className="pb-2 text-xs leading-5 text-muted-foreground">
              この画面の金額はご契約内容にもとづく試算です。正式な条件は
              「ご契約のしおり・約款」および更新のご案内書面をご確認ください。
            </p>
          </main>

          <BottomActionBar
            stack
            actions={
              <Button
                className="w-full"
                size="lg"
                disabled={!pathId}
                onClick={() => setConfirmOpen(true)}
              >
                {pathId ? "この内容で進む" : "上から道を選んでください"}
              </Button>
            }
          >
            <p className="text-sm" aria-live="polite">
              {pathId ? (
                <>
                  <span className="text-muted-foreground">選んだ道</span>{" "}
                  <span className="font-semibold">{PATH_LABEL[pathId]}</span>
                  <span className="ml-2 tabular-nums text-muted-foreground">
                    毎月 {formatYen(chosenPremium ?? 0)}
                  </span>
                </>
              ) : (
                <span className="text-muted-foreground">
                  まだ選んでいません。決めるのは {formatJpDate(APPLY_DEADLINE)} までです。
                </span>
              )}
            </p>
          </BottomActionBar>

          <ConfirmDialog
            open={confirmOpen}
            onOpenChange={setConfirmOpen}
            pathId={pathId}
            premium={chosenPremium}
            amountManYen={amountManYen}
            submitting={submitting}
            onSubmit={handleSubmit}
          />
        </>
      )}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/* いつまでに決めるか                                                          */
/* -------------------------------------------------------------------------- */

function DeadlineSection() {
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle as="h2" className="text-base">
          いつまでに決めるか
        </CardTitle>
        <CardDescription>
          締切をすぎると、下の「そのまま更新」になります。
        </CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        <Alert variant="warning" icon={<IconAlertTriangle />}>
          <AlertTitle>何もしないと、同じ保障内容で自動的に更新されます</AlertTitle>
          <AlertDescription>
            保障は続きますが、毎月の保険料は{" "}
            <strong className="font-semibold tabular-nums">{formatYen(policy.current.monthlyPremium)}</strong>{" "}から{" "}
            <strong className="font-semibold tabular-nums">{formatYen(policy.renewed.monthlyPremium)}</strong>{" "}
            になります。内容を変えたい場合だけ、締切までにお手続きが必要です。
          </AlertDescription>
        </Alert>

        <div className="rounded-lg border bg-card p-3">
          <p className="text-xs font-medium text-muted-foreground" id="deadline-badge-label">
            お手続きの締切
          </p>
          <div className="mt-1">
            <ExpiryBadge
              aria-labelledby="deadline-badge-label"
              value={APPLY_DEADLINE}
              today={TODAY}
              warnWithinDays={30}
              labels={{
                valid: "受付中",
                expiring: "締切が近づいています",
