function ReduceOutcome({
  amountManYen,
  onAmountChange,
  reducedPremium,
}: {
  amountManYen: number
  onAmountChange: (v: number) => void
  reducedPremium: number
}) {
  const diffFromNow = reducedPremium - policy.current.monthlyPremium
  const diffFromRenew = reducedPremium - policy.renewed.monthlyPremium

  function clampToStep(v: number) {
    const stepped = Math.round(v / AMOUNT_STEP) * AMOUNT_STEP
    return Math.min(AMOUNT_MAX, Math.max(AMOUNT_MIN, stepped))
  }

  return (
    <div className="flex flex-col gap-4">
      <p className="text-sm leading-6">
        保険金額を動かすと、毎月の保険料が変わります。
        {formatManYen(AMOUNT_MIN)}から{formatManYen(AMOUNT_MAX)}までの間で、
        {formatManYen(AMOUNT_STEP)}きざみで選べます。
      </p>

      <Slider
        label="保険金額"
        showValue
        min={AMOUNT_MIN}
        max={AMOUNT_MAX}
        step={AMOUNT_STEP}
        value={amountManYen}
        onValueChange={onAmountChange}
        formatValue={(v) => formatManYen(v)}
      />
      <div className="flex justify-between text-xs tabular-nums text-muted-foreground" aria-hidden="true">
        <span>{formatManYen(AMOUNT_MIN)}</span>
        <span>{formatManYen(AMOUNT_MAX)}</span>
      </div>

      <CurrencyInput
        label="金額を直接入れる（万円）"
        description={`${formatManYen(AMOUNT_STEP)}きざみに合わせて調整します`}
        currency="JPY"
        showSymbol={false}
        min={AMOUNT_MIN}
        max={AMOUNT_MAX}
        value={amountManYen}
        onValueChange={(v) => onAmountChange(clampToStep(v ?? AMOUNT_MIN))}
      />

      <div
        className="rounded-lg border bg-card p-3"
        role="status"
        aria-live="polite"
      >
        <p className="text-xs text-muted-foreground">この金額にした場合</p>
        <p className="mt-1 text-2xl font-bold tabular-nums">
          毎月 {formatYen(reducedPremium)}
        </p>
        <List variant="none" spacing="tight" className="mt-2 text-sm text-muted-foreground">
          <ListItem className="tabular-nums">
            いまの保険料（{formatYen(policy.current.monthlyPremium)}）とくらべて{" "}
            <strong className="font-semibold text-foreground">
              {diffFromNow >= 0 ? `${formatYen(diffFromNow)} 増えます` : `${formatYen(Math.abs(diffFromNow))} 減ります`}
            </strong>
          </ListItem>
          <ListItem className="tabular-nums">
            そのまま更新した場合（{formatYen(policy.renewed.monthlyPremium)}）とくらべて{" "}
            <strong className="font-semibold text-foreground">
              {formatYen(Math.abs(diffFromRenew))} 安くなります
            </strong>
          </ListItem>
          <ListItem className="tabular-nums">
            {policy.renewed.termYears}年分では{" "}
            <strong className="font-semibold text-foreground">
              {formatYen(Math.abs(diffFromRenew) * RENEWAL_MONTHS)} の差
            </strong>
            になります
          </ListItem>
        </List>
      </div>

      <Alert variant="warning" icon={<IconAlertTriangle />}>
        <AlertTitle>受け取れるお金も、同じだけ下がります</AlertTitle>
        <AlertDescription>
          万一のときに受け取れる金額は{" "}
          <strong className="tabular-nums">{formatManYen(policy.renewed.amountManYen)}</strong> から{" "}
          <strong className="tabular-nums">{formatManYen(amountManYen)}</strong> になります。
          住宅ローンの残りやお子さまの学費など、いま必要な金額と見くらべてお決めください。
        </AlertDescription>
      </Alert>
    </div>
  )
}

