function ConfirmDialog({
  open,
  onOpenChange,
  pathId,
  premium,
  amountManYen,
  submitting,
  onSubmit,
}: {
  open: boolean
  onOpenChange: (v: boolean) => void
  pathId: PathId | null
  premium: number | null
  amountManYen: number
  submitting: boolean
  onSubmit: () => void
}) {
  if (!pathId) return null

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>この内容で受け付けてよろしいですか</AlertDialogTitle>
          <AlertDialogDescription>
            {pathId === "stop" ? (
              <>
                {formatJpDate(NEW_TERM_START)}から保障がなくなります。
                {formatJpDate(MATURITY_DATE)}までは取り消せます。
              </>
            ) : (
              <>
                {PATH_LABEL[pathId]}
                {pathId === "reduce" && `（保険金額 ${formatManYen(amountManYen)}）`}
                。{formatJpDate(NEW_TERM_START)}から、毎月 {formatYen(premium ?? 0)} になります。
              </>
            )}
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={submitting}>もどる</AlertDialogCancel>
          <AlertDialogAction
            onClick={(event) => {
              event.preventDefault()
              onSubmit()
            }}
            disabled={submitting}
          >
            {submitting ? "送信中" : "受け付ける"}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

