        icon={<Icon icon={IconCircleCheck} size="xl" decorative className="text-success-strong" />}
        title="受け付けました"
        description={
          pathId === "stop"
            ? `${formatJpDate(MATURITY_DATE)}をもって保障が終わります。この日までは取り消せます。`
            : `${formatJpDate(NEW_TERM_START)}から、新しい条件になります。`
        }
        details={`受付番号 RN-2026-084412 / 受付日 ${formatJpDate(TODAY)}`}
        action={
          <Button variant="secondary" onClick={onBack}>
            契約の画面にもどる
          </Button>
        }
      />

      <Card>
        <CardHeader className="pb-3">
          <CardTitle as="h3" className="text-base">
            受け付けた内容
          </CardTitle>
        </CardHeader>
        <CardContent>
          <MetadataList
            variant="compact"
            wrap
            items={[
              { label: "選んだ道", value: PATH_LABEL[pathId] },
              {
                label: "保険金額",
                value: pathId === "stop" ? "なし（保障は終了）" : formatManYen(amountManYen),
              },
              {
                label: "毎月の保険料",
                value: pathId === "stop" ? "0円" : formatYen(premium),
              },
              {
                label: "新しい条件が始まる日",
                value: pathId === "stop" ? "なし" : formatJpDate(NEW_TERM_START),
              },
            ]}
          />
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle as="h3" className="text-base">
            このあとの流れ
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Timeline
            items={timelineFor(pathId).map((item, i) =>
              i === 0 ? { ...item, title: "受付が完了しました", variant: "success" as const } : item
            )}
          />
        </CardContent>
      </Card>

      <HelpSection />
    </main>
  )
}

